package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(reader, &n)
	var s string
	fmt.Fscan(reader, &s)
	countSF := 0
	countFS := 0
	for i := 0; i < len(s)-1; i++ {
		if s[i] == 'S' && s[i+1] == 'F' {
			countSF++
		} else if s[i] == 'F' && s[i+1] == 'S' {
			countFS++
		}
	}
	if countSF > countFS {
		fmt.Println("YES")
	} else {
		fmt.Println("NO")
	}
}
